import sys

MOD = 10**6 + 3

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    if n == 0:
        print(0)
        return

    size = 2 * n
    # grid[r][c] = 0 empty, 1 filled
    grid = [[0] * size for _ in range(size)]

    # prefix sum array for occupancy
    ps = [[0] * (size + 1) for _ in range(size + 1)]

    def build_prefix():
        for i in range(size):
            row_ps = ps[i + 1]
            prev_row_ps = ps[i]
            g_row = grid[i]
            s = 0
            for j in range(size):
                s += g_row[j]
                row_ps[j + 1] = row_ps[j] + s

    def area_sum(r1, c1, r2, c2):
        # inclusive r1,c1,r2,c2
        r1p, c1p, r2p, c2p = r1, c1, r2 + 1, c2 + 1
        return ps[r2p][c2p] - ps[r1p][c2p] - ps[r2p][c1p] + ps[r1p][c1p]

    def can_place(k, r, c):
        # check if k-cookie fits with top-left at (r,c)
        if r + k > size or c + k > size:
            return False
        # need all cells in the cookie shape empty
        # cookie occupies cells (i,j) with 0<=i,j<k and j>=i
        for i in range(k):
            # row r+i, columns c+i..c+k-1
            if area_sum(r + i, c + i, r + i, c + k - 1) != 0:
                return False
        return True

    def place(k, r, c):
        for i in range(k):
            row = grid[r + i]
            for j in range(c + i, c + k):
                row[j] = 1

    # simulate from largest cookie size down to 2
    for k in range(size, 1, -1):
        while True:
            build_prefix()
            placed = False
            for r in range(size - k + 1):
                for c in range(size - k + 1):
                    if can_place(k, r, c):
                        place(k, r, c)
                        placed = True
                        break
                if placed:
                    break
            if not placed:
                break

    # count empty cells
    empty = 0
    for i in range(size):
        for j in range(size):
            if grid[i][j] == 0:
                empty += 1

    print(empty % MOD)

if __name__ == "__main__":
    main()
